class Solution {
    public java.util.List<Integer> findClosestElements(int[] arr, int k, int x) {
        int lo = 0;
        int hi = arr.length - k;
        while (lo < hi) {
            int mid = lo + (hi - lo) / 2;
            if (x - arr[mid] > arr[mid + k] - x) {
                lo = mid + 1;
            } else {
                hi = mid;
            }
        }

        java.util.List<Integer> result = new java.util.ArrayList<>();
        for (int i = lo; i < lo + k; i++) {
            result.add(arr[i]);
        }
        return result;
    }
}

class Solution {
    public java.util.List<Integer> findClosestElements(int[] arr, int k, int x) {
        int left = 0;
        int right = arr.length - 1;
        while (right - left + 1 > k) {
            int leftDistance = Math.abs(arr[left] - x);
            int rightDistance = Math.abs(arr[right] - x);
            if (leftDistance <= rightDistance) {
                right--;
            } else {
                left++;
            }
        }

        java.util.List<Integer> result = new java.util.ArrayList<>();
        for (int i = left; i <= right; i++) {
            result.add(arr[i]);
        }
        return result;
    }
}

class Solution {
    public java.util.List<Integer> findClosestElements(int[] arr, int k, int x) {
        int lo = 0;
        int hi = arr.length;
        while (lo < hi) {
            int mid = lo + (hi - lo) / 2;
            if (arr[mid] < x) {
                lo = mid + 1;
            } else {
                hi = mid;
            }
        }

        int left = lo - 1;
        int right = lo;
        while (right - left - 1 < k) {
            if (left < 0) {
                right++;
            } else if (right == arr.length) {
                left--;
            } else if (x - arr[left] <= arr[right] - x) {
                left--;
            } else {
                right++;
            }
        }

        java.util.List<Integer> result = new java.util.ArrayList<>();
        for (int i = left + 1; i < right; i++) {
            result.add(arr[i]);
        }
        return result;
    }
}

class Solution {
    public java.util.List<Integer> findClosestElements(int[] arr, int k, int x) {
        java.util.PriorityQueue<Integer> heap = new java.util.PriorityQueue<>((a, b) -> {
            int distanceA = Math.abs(a - x);
            int distanceB = Math.abs(b - x);
            if (distanceA != distanceB) {
                return Integer.compare(distanceB, distanceA);
            }
            return Integer.compare(b, a);
        });

        for (int value : arr) {
            heap.offer(value);
            if (heap.size() > k) {
                heap.poll();
            }
        }

        java.util.List<Integer> result = new java.util.ArrayList<>(heap);
        java.util.Collections.sort(result);
        return result;
    }
}
